UPDATE /* DQ.updateDynamicQueryEntered */
       XXLGE_QUERY_EXEC_INSTR_RSLT_N
   SET batch_job_start_date           = SYSDATE
     , sql_error_content              = 'S02'
     , last_updated_by                = #{userId}
     , last_update_date               = SYSDATE
     , last_update_login              = #{userId}
 WHERE application_user_id            = #{userId}
   AND upload_session_id              = #{sessionId}
   AND query_id                       = #{queryId}
   AND org_id                         = #{defaultOrgId}

UPDATE /* DQ.updateDynamicQueryCompleted */
       XXLGE_QUERY_EXEC_INSTR_RSLT_N
   SET sql_execution_result_row_count = #{rowCount}
     , concurrent_request_id          = #{concurrentRequestId}
     , batch_job_end_date             = SYSDATE
     , sql_error_content              = #{rsltStatusCode}
     , result_content                 = #{resultContent}
     , last_updated_by                = #{userId}
     , last_update_date               = SYSDATE
     , last_update_login              = #{userId}
 WHERE application_user_id            = #{userId}
   AND upload_session_id              = #{sessionId}
   AND query_id                       = #{queryId}
   AND org_id                         = #{defaultOrgId}
